#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Analyze European economic performance data found in the workspace.
Extracts tabular data from files, normalizes records to (label, year, value),
computes statistics (trends, growth, rankings), and prints a draft
data-storytelling report to stdout so it can be turned into a final report.
"""
import os, re, json, csv, io, statistics
from pathlib import Path

ROOT = Path(os.getcwd())
MAX_SIZE = 2_000_000


def list_files(root):
    out = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if not d.startswith('.')]
        for f in sorted(filenames):
            if f.startswith('.') or f.endswith('.py'):
                continue
            p = Path(dirpath) / f
            try:
                sz = p.stat().st_size
            except OSError:
                sz = -1
            out.append((p, sz))
    return out


def to_float(s):
    if s is None:
        return None
    if isinstance(s, (int, float)):
        return float(s)
    t = str(s).strip()
    if not t or t.lower() in {'n/a', 'na', '-', '—', '–', '..', '...', 'nan', 'null', 'none'}:
        return None
    t = t.replace('\u2212', '-').replace('\u2013', '-')
    t = re.sub(r'[€$£%\s\u00a0\u202f]+', '', t)
    if not t:
        return None
    if t.startswith('(') and t.endswith(')'):
        t = '-' + t[1:-1]
    suffix = 1.0
    if t and t[-1] in 'kKmMbBtT':
        suffix = {'k': 1e3, 'm': 1e6, 'b': 1e9, 't': 1e12}[t[-1].lower()]
        t = t[:-1]
    if not re.fullmatch(r'[-+]?[\d.,]+', t):
        return None
    if ',' in t and '.' in t:
        if t.rfind(',') > t.rfind('.'):
            t = t.replace('.', '').replace(',', '.')
        else:
            t = t.replace(',', '')
    elif ',' in t:
        t = t.replace(',', '.')
    if t.count('.') > 1:
        t = t.replace('.', '')
    try:
        return float(t) * suffix
    except ValueError:
        return None


def is_year(v):
    f = to_float(v)
    return bool(f is not None and f == int(f) and 1900 <= f <= 2100)


def clean_rows(rows, delim):
    out = []
    for r in rows:
        rr = [c.strip() for c in r]
        if delim == '|':
            while rr and rr[0] == '':
                rr.pop(0)
            while rr and rr[-1] == '':
                rr.pop()
        out.append(rr)
    out = [r for r in out if not (r and all(re.fullmatch(r'[-: ]+', c or '') for c in r))]
    out = [r for r in out if any(c for c in r)]
    return out


def parse_csv(p):
    encodings = ['utf-8-sig', 'utf-8', 'latin-1', 'cp1252']
    delims = [',', ';', '\t', '|']
    best = None
    for enc in encodings:
        try:
            raw = p.read_bytes().decode(enc)
        except Exception:
            continue
        for d in delims:
            try:
                rows = list(csv.reader(io.StringIO(raw), delimiter=d))
            except Exception:
                continue
            rows = clean_rows(rows, d)
            if len(rows) < 2:
                continue
            ncols = max(len(r) for r in rows)
            if ncols < 2:
                continue
            widths = [len(r) for r in rows]
            try:
                mode_w = statistics.mode(widths)
            except Exception:
                mode_w = ncols
            consistent = sum(1 for w in widths if w == mode_w) / len(widths)
            score = consistent
            if d == ',':
                score += 0.08
            elif d == '\t':
                score += 0.06
            elif d == '|':
                score += 0.04
            flat = [c for r in rows for c in r if c]
            num = sum(1 for c in flat if to_float(c) is not None)
            score += min(0.2, num / max(1, len(flat)) * 0.2)
            if best is None or score > best[0]:
                best = (score, enc, d, rows)
    if best is None:
        return None
    _, enc, d, rows = best
    header_idx = 0
    for i, r in enumerate(rows[:6]):
        if not r:
            continue
        nonnum = sum(1 for c in r if to_float(c) is None)
        if nonnum >= max(1, int(len(r) * 0.5)):
            header_idx = i
            break
    header = [c.strip() for c in rows[header_idx]]
    data = rows[header_idx + 1:]
    ncols = len(header)
    data = [r[:ncols] + [''] * (ncols - len(r)) for r in data]
    return {'name': p.name, 'header': header, 'rows': data}


def parse_json(p):
    try:
        raw = p.read_text(encoding='utf-8-sig')
    except Exception:
        try:
            raw = p.read_text(encoding='utf-8')
        except Exception:
            return None
    try:
        obj = json.loads(raw)
    except Exception:
        return None
    if isinstance(obj, list) and obj and all(isinstance(x, dict) for x in obj):
        header = list(obj[0].keys())
        rows = [[str(x.get(h, '')) for h in header] for x in obj]
        return {'name': p.name, 'header': header, 'rows': rows}
    if isinstance(obj, dict):
        lists = {k: v for k, v in obj.items() if isinstance(v, list) and v}
        if lists:
            n = len(next(iter(lists.values())))
            if all(len(v) == n for v in lists.values()):
                header = list(lists.keys())
                rows = [[str(lists[h][i]) for h in header] for i in range(n)]
                return {'name': p.name, 'header': header, 'rows': rows}
    return None


def parse_file(p):
    t = parse_csv(p)
    if t and len(t['rows']) >= 1:
        return t
    return parse_json(p)


def detect_wide(t):
    header = t['header']
    yrs = [i for i, h in enumerate(header) if is_year(h)]
    if len(yrs) >= 2 and len(yrs) / len(header) >= 0.4:
        return yrs
    return None


def pivot_wide(t):
    header = t['header']
    year_cols = [(i, int(to_float(h))) for i, h in enumerate(header) if is_year(h)]
    if len(year_cols) < 2:
        return []
    label_idx = [i for i in range(len(header)) if i not in [c for c, _ in year_cols]]
    if not label_idx:
        label_idx = [0]
    li = label_idx[0]
    recs = []
    for r in t['rows']:
        if li >= len(r):
            continue
        label = str(r[li]).strip() or f'row{len(recs)}'
        for ci, yr in year_cols:
            if ci >= len(r):
                continue
            v = to_float(r[ci])
            if v is None:
                continue
            recs.append({'label': label, 'year': yr, 'value': v})
    return recs


def long_datasets(t, yrcol):
    header = t['header']
    ncols = len(header)
    label_col = None
    for i in range(ncols):
        if i == yrcol:
            continue
        vals = [r[i] for r in t['rows'] if i < len(r)]
        if not vals:
            continue
        num = sum(1 for v in vals if to_float(v) is not None)
        if num / len(vals) < 0.5:
            label_col = i
            break
    if label_col is None:
        label_col = 0 if yrcol != 0 else 1
    out = {}
    for i in range(ncols):
        if i == yrcol or i == label_col:
            continue
        vals = [r[i] for r in t['rows'] if i < len(r)]
        num = sum(1 for v in vals if to_float(v) is not None)
        if num / max(1, len(vals)) < 0.5:
            continue
        recs = []
        for r in t['rows']:
            if max(i, yrcol, label_col) >= len(r):
                continue
            yr = to_float(r[yrcol])
            if yr is None or yr != int(yr):
                continue
            v = to_float(r[i])
            if v is None:
                continue
            recs.append({'label': str(r[label_col]).strip() or f'row{len(recs)}',
                         'year': int(yr), 'value': v})
        if recs:
            out[header[i].strip()] = recs
    return out


def find_year_col(t):
    header = t['header']
    ncols = len(header)
    best_idx, best_score = None, 0.0
    for i in range(ncols):
        vals = [r[i] for r in t['rows'] if i < len(r)]
        if not vals:
            continue
        ys = sum(1 for v in vals if is_year(v))
        score = ys / len(vals)
        if score > best_score:
            best_idx, best_score = i, score
    return best_idx if best_score >= 0.5 else None


def dedup(recs):
    d = {}
    for r in recs:
        key = (r['label'], r['year'])
        d.setdefault(key, []).append(r['value'])
    out = []
    for (lb, yr), vals in d.items():
        out.append({'label': lb, 'year': yr, 'value': sum(vals) / len(vals)})
    return out


def compute_stats(recs):
    recs = dedup(recs)
    labels = sorted({r['label'] for r in recs})
    years = sorted({r['year'] for r in recs})
    per = {lb: sorted([r for r in recs if r['label'] == lb], key=lambda r: r['year']) for lb in labels}
    rows = []
    for lb in labels:
        pts = per[lb]
        first, last = pts[0], pts[-1]
        chg = last['value'] - first['value']
        pct = (last['value'] / first['value'] - 1) * 100 if first['value'] else None
        ny = last['year'] - first['year']
        ann = ((last['value'] / first['value']) ** (1.0 / ny) - 1) * 100 if (first['value'] and ny > 0) else None
        xs = [p['year'] for p in pts]
        ys = [p['value'] for p in pts]
        n = len(pts)
        mx = sum(xs) / n
        my = sum(ys) / n
        var = sum((x - mx) ** 2 for x in xs)
        slope = sum((xs[i] - mx) * (ys[i] - my) for i in range(n)) / var if var else 0.0
        rows.append({'label': lb, 'first': first['value'], 'first_year': first['year'],
                     'last': last['value'], 'last_year': last['year'],
                     'chg': chg, 'pct': pct, 'ann': ann, 'slope': slope, 'n': len(pts)})
    latest_year = years[-1]
    latest = [r for r in rows if r['last_year'] == latest_year]
    return {'labels': labels, 'years': years, 'rows': rows,
            'latest_year': latest_year, 'latest': latest}


def fmt(v, nd=1):
    if v is None:
        return 'n/a'
    return f'{v:,.{nd}f}'


def metric_name(t, path):
    stem = Path(path).stem
    stem = stem.replace('_', ' ').replace('-', ' ').strip().title()
    return stem or t['name']


def print_draft(datasets):
    print('=' * 78)
    print('DRAFT DATA-STORYTELLING REPORT (numbers computed from the data)')
    print('=' * 78)
    if not datasets:
        print('No usable tabular datasets were found in the workspace.')
        return
    for idx, ds in enumerate(datasets):
        st = compute_stats(ds['records'])
        print()
        print(f'## Dataset {idx + 1}: {ds["name"]}  (source: {ds["source"]}, {ds["kind"]})')
        print(f'Coverage: {st["years"][0]}-{st["years"][-1]}  |  {len(st["labels"])} labels  |  latest year: {st["latest_year"]}')
        rows = sorted(st['rows'], key=lambda r: (r['last'] is None, -(r['last'] or 0)))
        print()
        print('Ranking by latest value:')
        print(f'{"Label":<30}{"First":>13}{"Last":>13}{"Chg":>13}{"Pct%":>10}{"Ann%":>9}')
        for r in rows:
            print(f'{str(r["label"])[:30]:<30}{fmt(r["first"], 2):>13}{fmt(r["last"], 2):>13}'
                  f'{fmt(r["chg"], 2):>13}{fmt(r["pct"], 1):>10}{fmt(r["ann"], 1):>9}')
        pos = [r for r in rows if r['pct'] is not None and r['pct'] > 0]
        neg = [r for r in rows if r['pct'] is not None and r['pct'] < 0]
        best = max(pos, key=lambda r: r['pct']) if pos else None
        worst = min(neg, key=lambda r: r['pct']) if neg else None
        largest = max(rows, key=lambda r: r['last'] or 0)
        avg_slope = statistics.mean([r['slope'] for r in rows]) if rows else 0.0
        print()
        print(f'Insight: largest latest value = {largest["label"]} ({fmt(largest["last"], 2)})')
        if best:
            print(f'Fastest growth = {best["label"]} ({fmt(best["pct"], 1)}% over {best["first_year"]}-{best["last_year"]}, {fmt(best["ann"], 1)}%/yr)')
        if worst:
            print(f'Weakest/declining = {worst["label"]} ({fmt(worst["pct"], 1)}% over {worst["first_year"]}-{worst["last_year"]})')
        print(f'Share of labels improving: {len(pos)}/{len(rows)}; average trend slope: {avg_slope:+.3f}/year')
        if st['latest']:
            lv = [r['last'] for r in st['latest'] if r['last'] is not None]
            if lv:
                print(f'Latest-year cross-section: min={fmt(min(lv), 2)}, median={fmt(statistics.median(lv), 2)}, '
                      f'mean={fmt(statistics.mean(lv), 2)}, max={fmt(max(lv), 2)}')
    print()
    print('=' * 78)


def main():
    files = list_files(ROOT)
    print('=' * 78)
    print('WORKSPACE FILES')
    for p, sz in files:
        print(f'  {p.relative_to(ROOT)}  ({sz} bytes)')
    print('=' * 78)

    tables = []
    for p, sz in files:
        if sz <= 0 or sz > MAX_SIZE:
            continue
        t = parse_file(p)
        if not t:
            continue
        t['path'] = str(p.relative_to(ROOT))
        tables.append(t)
        print(f'[PARSED] {t["path"]}: {len(t["rows"])} rows x {len(t["header"])} cols | header={t["header"]}')
        for r in t['rows'][:5]:
            print('   ', r)
    print('=' * 78)

    datasets = []
    for t in tables:
        wide = detect_wide(t)
        if wide is not None:
            recs = pivot_wide(t)
            if len(recs) >= 2:
                datasets.append({'name': metric_name(t, t['path']), 'source': t['path'],
                                 'records': recs, 'kind': 'wide'})
        else:
            yrcol = find_year_col(t)
            if yrcol is not None:
                per_metric = long_datasets(t, yrcol)
                for mname, recs in per_metric.items():
                    if len(recs) >= 2:
                        datasets.append({'name': mname, 'source': t['path'],
                                         'records': recs, 'kind': 'long'})
    if not datasets:
        # fall back: treat each parsed table as a simple label/value snapshot
        for t in tables:
            header = t['header']
            rows = t['rows']
            if len(header) >= 2 and rows:
                recs = []
                for r in rows:
                    if len(r) < 2:
                        continue
                    v = to_float(r[1])
                    if v is None:
                        continue
                    recs.append({'label': str(r[0]).strip(), 'year': 0, 'value': v})
                if len(recs) >= 2:
                    datasets.append({'name': metric_name(t, t['path']), 'source': t['path'],
                                     'records': recs, 'kind': 'snapshot'})

    print(f'Normalized datasets: {len(datasets)}')
    for ds in datasets:
        yrs = sorted({r['year'] for r in ds['records']})
        print(f'  - {ds["name"]} ({ds["source"]}, {ds["kind"]}): {len(ds["records"])} records, '
              f'years {yrs[0]}-{yrs[-1]}, labels={len({r["label"] for r in ds["records"]})}')
    print('=' * 78)

    print_draft(datasets)


if __name__ == '__main__':
    try:
        main()
    except Exception:
        import traceback
        traceback.print_exc()
        raise SystemExit(1)

