            continue
        label = str(r[li]).strip() or f'row{len(recs)}'
        for ci, yr in year_cols:
            if ci >= len(r):
                continue
            v = to_float(r[ci])
            if v is None:
                continue
            recs.append({'label': label, 'year': yr, 'value': v})
    return recs


def long_datasets(t, yrcol):
    header = t['header']
    ncols = len(header)
    label_col = None
    for i in range(ncols):
        if i == yrcol:
            continue
        vals = [r[i] for r in t['rows'] if i < len(r)]
        if not vals:
            continue
        num = sum(1 for v in vals if to_float(v) is not None)
        if num / len(vals) < 0.5:
            label_col = i
            break
    if label_col is None:
        label_col = 0 if yrcol != 0 else 1
    out = {}
    for i in range(ncols):
        if i == yrcol or i == label_col:
            continue
        vals = [r[i] for r in t['rows'] if i < len(r)]
        num = sum(1 for v in vals if to_float(v) is not None)
        if num / max(1, len(vals)) < 0.5:
            continue
        recs = []
        for r in t['rows']:
            if max(i, yrcol, label_col) >= len(r):
                continue
            yr = to_float(r[yrcol])
            if yr is None or yr != int(yr):
                continue
            v = to_float(r[i])
            if v is None:
                continue
            recs.append({'label': str(r[label_col]).strip() or f'row{len(recs)}',
                         'year': int(yr), 'value': v})
        if recs:
            out[header[i].strip()] = recs
    return out


def find_year_col(t):
    header = t['header']
    ncols = len(header)
    best_idx, best_score = None, 0.0
    for i in range(ncols):
        vals = [r[i] for r in t['rows'] if i < len(r)]
        if not vals:
            continue
        ys = sum(1 for v in vals if is_year(v))
        score = ys / len(vals)
        if score > best_score:
            best_idx, best_score = i, score
    return best_idx if best_score >= 0.5 else None


def dedup(recs):
    d = {}
    for r in recs:
        key = (r['label'], r['year'])
        d.setdefault(key, []).append(r['value'])
    out = []
    for (lb, yr), vals in d.items():
        out.append({'label': lb, 'year': yr, 'value': sum(vals) / len(vals)})
    return out


def compute_stats(recs):
    recs = dedup(recs)
    labels = sorted({r['label'] for r in recs})
    years = sorted({r['year'] for r in recs})
    per = {lb: sorted([r for r in recs if r['label'] == lb], key=lambda r: r['year']) for lb in labels}
    rows = []
    for lb in labels:
        pts = per[lb]
        first, last = pts[0], pts[-1]
        chg = last['value'] - first['value']
        pct = (last['value'] / first['value'] - 1) * 100 if first['value'] else None
        ny = last['year'] - first['year']
        ann = ((last['value'] / first['value']) ** (1.0 / ny) - 1) * 100 if (first['value'] and ny > 0) else None
        xs = [p['year'] for p in pts]
        ys = [p['value'] for p in pts]
        n = len(pts)
        mx = sum(xs) / n
        my = sum(ys) / n
        var = sum((x - mx) ** 2 for x in xs)
        slope = sum((xs[i] - mx) * (ys[i] - my) for i in range(n)) / var if var else 0.0
        rows.append({'label': lb, 'first': first['value'], 'first_year': first['year'],
                     'last': last['value'], 'last_year': last['year'],
                     'chg': chg, 'pct': pct, 'ann': ann, 'slope': slope, 'n': len(pts)})
    latest_year = years[-1]
    latest = [r for r in rows if r['last_year'] == latest_year]
    return {'labels': labels, 'years': years, 'rows': rows,
            'latest_year': latest_year, 'latest': latest}


def fmt(v, nd=1):
    if v is None:
        return 'n/a'
    return f'{v:,.{nd}f}'


def metric_name(t, path):
    stem = Path(path).stem
    stem = stem.replace('_', ' ').replace('-', ' ').strip().title()
    return stem or t['name']


def print_draft(datasets):
    print('=' * 78)
    print('DRAFT DATA-STORYTELLING REPORT (numbers computed from the data)')
    print('=' * 78)
    if not datasets:
        print('No usable tabular datasets were found in the workspace.')
        return
    for idx, ds in enumerate(datasets):
        st = compute_stats(ds['records'])
        print()
        print(f'## Dataset {idx + 1}: {ds["name"]}  (source: {ds["source"]}, {ds["kind"]})')
        print(f'Coverage: {st["years"][0]}-{st["years"][-1]}  |  {len(st["labels"])} labels  |  latest year: {st["latest_year"]}')
        rows = sorted(st['rows'], key=lambda r: (r['last'] is None, -(r['last'] or 0)))
        print()
        print('Ranking by latest value:')
        print(f'{"Label":<30}{"First":>13}{"Last":>13}{"Chg":>13}{"Pct%":>10}{"Ann%":>9}')
        for r in rows:
            print(f'{str(r["label"])[:30]:<30}{fmt(r["first"], 2):>13}{fmt(r["last"], 2):>13}'
                  f'{fmt(r["chg"], 2):>13}{fmt(r["pct"], 1):>10}{fmt(r["ann"], 1):>9}')
        pos = [r for r in rows if r['pct'] is not None and r['pct'] > 0]
        neg = [r for r in rows if r['pct'] is not None and r['pct'] < 0]
        best = max(pos, key=lambda r: r['pct']) if pos else None
        worst = min(neg, key=lambda r: r['pct']) if neg else None
        largest = max(rows, key=lambda r: r['last'] or 0)
        avg_slope = statistics.mean([r['slope'] for r in rows]) if rows else 0.0
        print()
        print(f'Insight: largest latest value = {largest["label"]} ({fmt(largest["last"], 2)})')
        if best:
            print(f'Fastest growth = {best["label"]} ({fmt(best["pct"], 1)}% over {best["first_year"]}-{best["last_year"]}, {fmt(best["ann"], 1)}%/yr)')
        if worst:
            print(f'Weakest/declining = {worst["label"]} ({fmt(worst["pct"], 1)}% over {worst["first_year"]}-{worst["last_year"]})')
        print(f'Share of labels improving: {len(pos)}/{len(rows)}; average trend slope: {avg_slope:+.3f}/year')
        if st['latest']:
            lv = [r['last'] for r in st['latest'] if r['last'] is not None]
            if lv:
                print(f'Latest-year cross-section: min={fmt(min(lv), 2)}, median={fmt(statistics.median(lv), 2)}, '
                      f'mean={fmt(statistics.mean(lv), 2)}, max={fmt(max(lv), 2)}')
    print()
    print('=' * 78)


def main():
    files = list_files(ROOT)
    print('=' * 78)
    print('WORKSPACE FILES')
    for p, sz in files:
        print(f'  {p.relative_to(ROOT)}  ({sz} bytes)')
    print('=' * 78)

    tables = []
    for p, sz in files:
        if sz <= 0 or sz > MAX_SIZE:
            continue
        t = parse_file(p)
        if not t:
            continue
        t['path'] = str(p.relative_to(ROOT))
        tables.append(t)
        print(f'[PARSED] {t["path"]}: {len(t["rows"])} rows x {len(t["header"])} cols | header={t["header"]}')
        for r in t['rows'][:5]:
            print('   ', r)
    print('=' * 78)

    datasets = []
    for t in tables:
        wide = detect_wide(t)
        if wide is not None:
            recs = pivot_wide(t)
            if len(recs) >= 2:
                datasets.append({'name': metric_name(t, t['path']), 'source': t['path'],
                                 'records': recs, 'kind': 'wide'})
        else:
            yrcol = find_year_col(t)
            if yrcol is not None:
                per_metric = long_datasets(t, yrcol)
                for mname, recs in per_metric.items():
                    if len(recs) >= 2:
                        datasets.append({'name': mname, 'source': t['path'],
                                         'records': recs, 'kind': 'long'})
    if not datasets:
        # fall back: treat each parsed table as a simple label/value snapshot
        for t in tables:
            header = t['header']
            rows = t['rows']
            if len(header) >= 2 and rows:
                recs = []
                for r in rows:
                    if len(r) < 2:
                        continue
                    v = to_float(r[1])
                    if v is None:
                        continue
                    recs.append({'label': str(r[0]).strip(), 'year': 0, 'value': v})
                if len(recs) >= 2:
                    datasets.append({'name': metric_name(t, t['path']), 'source': t['path'],
                                     'records': recs, 'kind': 'snapshot'})

    print(f'Normalized datasets: {len(datasets)}')
    for ds in datasets:
        yrs = sorted({r['year'] for r in ds['records']})
        print(f'  - {ds["name"]} ({ds["source"]}, {ds["kind"]}): {len(ds["records"])} records, '
              f'years {yrs[0]}-{yrs[-1]}, labels={len({r["label"] for r in ds["records"]})}')
    print('=' * 78)

    print_draft(datasets)


if __name__ == '__main__':
    try:
        main()
    except Exception:
        import traceback
        traceback.print_exc()
        raise SystemExit(1)
